using System.ComponentModel.DataAnnotations;
using System.ComponentModel.DataAnnotations.Schema;
using Microsoft.EntityFrameworkCore;

namespace DMS.Data.EF.Models.Features;

// EF entities for the tables added by the Database scripts (005, 006, 008, 010, 012, 013, 015, 019).
// Keys come from Proc_NextID (or are the vessel ID), so they are not generated by the database unless marked Identity.
// They are mapped in GeneralContext (see FeatureModel); Notification_Read is mapped in every context that uses it.

// ------------------------------------------------------------------------------------------------ Suggestions (012)

[Table("SUG_Master")]
public class SugMaster
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long SUG_MasterID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    [StringLength(30), Unicode(false)] public string? SuggestionNo { get; set; }
    [StringLength(250)] public string Title { get; set; } = "";
    public string? Description { get; set; }
    [StringLength(20), Unicode(false)] public string? ItemType { get; set; }
    public long? ItemID { get; set; }
    [StringLength(1000)] public string? QuotedText { get; set; }
    [StringLength(10), Unicode(false)] public string Priority { get; set; } = "Medium";
    [StringLength(20), Unicode(false)] public string Status { get; set; } = "Submitted";
    [StringLength(50), Unicode(false)] public string SubmittedBy { get; set; } = "";
    [StringLength(250)] public string? SubmittedByName { get; set; }
    [StringLength(50), Unicode(false)] public string? SubmittedRank { get; set; }
    [Column(TypeName = "datetime")] public DateTime SubmittedOn { get; set; }
    [StringLength(50), Unicode(false)] public string? AssignedTo { get; set; }
    [StringLength(20), Unicode(false)] public string? ImplementedItemType { get; set; }
    public long? ImplementedItemID { get; set; }
    [Column(TypeName = "datetime")] public DateTime? ModifiedOn { get; set; }
    public int IsDeleted { get; set; }
}

[Table("SUG_Log")]
public class SugLog
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long SUG_LogID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    public long SUG_MasterID { get; set; }
    [StringLength(20), Unicode(false)] public string? Status { get; set; }
    [StringLength(2000)] public string? Comment { get; set; }
    [StringLength(50), Unicode(false)] public string? UserID { get; set; }
    [StringLength(250)] public string? UserName { get; set; }
    [Column(TypeName = "datetime")] public DateTime LogDate { get; set; }
}

[Table("SUG_Blob")]
public class SugBlob
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long SUG_BlobID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    public long SUG_MasterID { get; set; }
    [StringLength(250)] public string? FileName { get; set; }
    [StringLength(50), Unicode(false)] public string? FileType { get; set; }
    public int BlobSize { get; set; }
    public byte[]? BlobContents { get; set; }
    [Column(TypeName = "datetime")] public DateTime? AddedOn { get; set; }
}

// ------------------------------------------------------------------------------------------------ Inbox (012) and notification reads (015)

[Table("DMS_Inbox")]
public class DmsInbox
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long DMS_InboxID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    [StringLength(20), Unicode(false)] public string ItemType { get; set; } = "";
    public long ItemID { get; set; }
    public long? VersionID { get; set; }
    [StringLength(20), Unicode(false)] public string Action { get; set; } = "";
    [StringLength(500)] public string? Title { get; set; }
    public int? Priority { get; set; }
    [StringLength(50), Unicode(false)] public string? TargetUserID { get; set; }
    [StringLength(50), Unicode(false)] public string? TargetRank { get; set; }
    [Column(TypeName = "datetime")] public DateTime CreatedOn { get; set; }
    public int IsActive { get; set; } = 1;
}

[Table("DMS_InboxRead")]
public class DmsInboxRead
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long DMS_InboxReadID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    public long DMS_InboxID { get; set; }
    [StringLength(50), Unicode(false)] public string UserID { get; set; } = "";
    [Column(TypeName = "datetime")] public DateTime ReadOn { get; set; }
}

/// <summary>dbo.Notification_Read (015): which office user has read which manual / circular notification.</summary>
[Table("Notification_Read")]
[PrimaryKey(nameof(Module), nameof(UserID), nameof(NotificationID))]
public class NotificationRead
{
    [StringLength(3), Unicode(false)] public string Module { get; set; } = "";
    public long NotificationID { get; set; }
    [StringLength(50), Unicode(false)] public string UserID { get; set; } = "";
    [Column(TypeName = "datetime2(0)")] public DateTime ReadOn { get; set; }
}

// ------------------------------------------------------------------------------------------------ Circular - manual links (012)

[Table("CIR_ManualLink")]
public class CirManualLink
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public long CIR_ManualLinkID { get; set; }
    [StringLength(3), Unicode(false)] public string Origin { get; set; } = "HQ";
    public int VesselID { get; set; }
    public long CIR_MasterID { get; set; }
    public long DM_ManualID { get; set; }
    public long? DM_ManualVersionID { get; set; }
    [StringLength(20), Unicode(false)] public string LinkType { get; set; } = "";
    [StringLength(500)] public string? Remarks { get; set; }
    public int IsActive { get; set; } = 1;
    [Column(TypeName = "datetime")] public DateTime? ClosedOn { get; set; }
    [StringLength(50), Unicode(false)] public string? CreatedBy { get; set; }
    [Column(TypeName = "datetime")] public DateTime? CreatedOn { get; set; }
}

// ------------------------------------------------------------------------------------------------ Attachment storage (019)

[Table("BlobTableSettings")]
public class BlobTableSettingRow
{
    [Key, StringLength(150), Unicode(false)] public string TableName { get; set; } = "";
    [StringLength(150), Unicode(false)] public string? Cloud_AccountName { get; set; }
    [StringLength(500), Unicode(false)] public string? Cloud_AccountKey { get; set; }
    [StringLength(150), Unicode(false)] public string? Cloud_ContainerName { get; set; }
    [StringLength(150), Unicode(false)] public string? Cloud_Directory { get; set; }
    [StringLength(50)] public string? HQ_Storage_Option { get; set; }
    [StringLength(150)] public string? HQ_Local_Folder { get; set; }
    [StringLength(150)] public string? HQ_DatabaseName { get; set; }
    [StringLength(50)] public string? VSL_Storage_Option { get; set; }
    [StringLength(150)] public string? VSL_DatabaseName { get; set; }
    [StringLength(150)] public string? VSL_Local_Folder { get; set; }
}

// ------------------------------------------------------------------------------------------------ Vessel sync (005, 006, 008, 010)

[Table("Sync_Vessel")]
public class SyncVessel
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public int VesselID { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? LastContactUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? LastSuccessUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? LastPullUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? LastPushUtc { get; set; }
    [StringLength(20)] public string? LastStatus { get; set; }
    [StringLength(1000)] public string? LastError { get; set; }
    public int PendingOnShip { get; set; }
    [StringLength(100)] public string? CurrentActivity { get; set; }
    public int? ProgressPercent { get; set; }
    [StringLength(50)] public string? AppVersion { get; set; }
}

[Table("Sync_Log")]
public class Sync_Log
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long Sync_LogID { get; set; }
    public int VesselID { get; set; }
    [StringLength(10)] public string Direction { get; set; } = "";
    [Column(TypeName = "datetime2(3)")] public DateTime StartedUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? FinishedUtc { get; set; }
    public int ItemsCount { get; set; }
    [StringLength(20)] public string Status { get; set; } = "";
    [StringLength(1000)] public string? Error { get; set; }
}

[Table("Sync_VesselKey")]
public class SyncVesselKey
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.None)] public int VesselID { get; set; }
    [Column(TypeName = "char(64)")] public string KeyHash { get; set; } = "";
    public bool IsActive { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime CreatedUtc { get; set; }
    [StringLength(150)] public string? CreatedBy { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? LastUsedUtc { get; set; }
}

[Table("Sync_Outbox")]
public class SyncOutbox
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long SyncOutboxID { get; set; }
    public int VesselID { get; set; }
    [StringLength(20)] public string ItemType { get; set; } = "";
    public long ItemID { get; set; }
    [Column(TypeName = "char(1)")] public string Action { get; set; } = "";
    [StringLength(128)] public string SourceTable { get; set; } = "";
    [Column(TypeName = "datetime2(3)")] public DateTime CreatedUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? SentUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? DownloadedUtc { get; set; }
}

[Table("Sync_FullCopyItem")]
[PrimaryKey(nameof(VesselID), nameof(ItemType), nameof(ItemID))]
public class SyncFullCopyItem
{
    public int VesselID { get; set; }
    [StringLength(20)] public string ItemType { get; set; } = "";
    public long ItemID { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime AddedUtc { get; set; }
}

[Table("Sync_ChangeLog")]
public class SyncChangeLog
{
    [Key, DatabaseGenerated(DatabaseGeneratedOption.Identity)] public long SyncChangeID { get; set; }
    public int VesselID { get; set; }
    [StringLength(128), Unicode(false)] public string TableName { get; set; } = "";
    public long KeyValue { get; set; }
    [Column(TypeName = "char(1)")] public string Action { get; set; } = "";
    [Column(TypeName = "datetime2(3)")] public DateTime CreatedUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? SentUtc { get; set; }
    [Column(TypeName = "datetime2(3)")] public DateTime? DownloadedUtc { get; set; }
}

// ------------------------------------------------------------------------------------------------ Results of stored procedures

/// <summary>dbo.Api_SyncTableColumns: one row per column of each active synced table (Sync_Table).</summary>
[Keyless]
public class SyncTableColumnRow
{
    public string TableName { get; set; } = "";
    public int SortOrder { get; set; }
    public string? BlobColumn { get; set; }
    public bool AllVessels { get; set; }
    public string? KeyColumn { get; set; }
    public bool HasVesselColumn { get; set; }
    public string ColumnName { get; set; } = "";
}

/// <summary>dbo.Api_VesselIdRanges: the start of each vessel's ID range (V_Vessel.TableIDstart, when the column exists).</summary>
[Keyless]
public class VesselIdRangeRow
{
    public int VesselID { get; set; }
    public long? TableIDstart { get; set; }
}
